import "../css/TrackOrders.css";

import { useState, useEffect } from 'react';

export function TrackOrders() {
    const [orders, setOrders] = useState([]);

    useEffect(() => {
        // Fetch orders from the backend API
        fetchOrders();
    }, []);

    const fetchOrders = async () => {
        try {
            const response = await fetch('http://localhost:5000/orders/placed'); // Replace with your backend API endpoint
            const data = await response.json();
            setOrders(data);
        } catch (error) {
            console.error('Error fetching orders:', error);
        }
    }

  return (
    <div>
      <h1>Track Orders</h1>
        <table>
          <thead>
            <tr>
              <th>Order ID</th>
              <th>Product</th>
              <th>Quantity</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {orders.map(order => (
              <tr key={order.id}>
                <td>{order.id}</td>
                <td>{order.product}</td>
                <td>{order.quantity}</td>
                <td>{order.status}</td>
              </tr>
            ))}
          </tbody>
        </table>

    </div>
  );
}
